//! Raw FFmpeg bindings (generated by build.rs) plus the few bits bindgen cannot express.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code, clippy::all)]

use std::ffi::{c_char, c_void, CStr};

include!(concat!(env!("OUT_DIR"), "/ffmpeg.rs"));

pub const AVERROR_EAGAIN: i32 = -11;
pub const AVERROR_EOF: i32 = -0x2046_4F45; // FFERRTAG('E','O','F',' ')

/// libavutil/hwcontext_d3d11va.h, declared by hand so that bindgen does not have to
/// chew through the whole of d3d11.h.
#[repr(C)]
pub struct AVD3D11VADeviceContext {
    pub device: *mut c_void,
    pub device_context: *mut c_void,
    pub video_device: *mut c_void,
    pub video_context: *mut c_void,
    pub lock: Option<unsafe extern "C" fn(*mut c_void)>,
    pub unlock: Option<unsafe extern "C" fn(*mut c_void)>,
    pub lock_ctx: *mut c_void,
    pub BindFlags: u32,
    pub MiscFlags: u32,
}

#[repr(C)]
pub struct AVD3D11VAFramesContext {
    pub texture: *mut c_void,
    pub BindFlags: u32,
    pub MiscFlags: u32,
    pub texture_infos: *mut c_void,
}

pub fn err_text(code: i32) -> String {
    let mut buf = [0 as c_char; 256];
    unsafe {
        av_strerror(code, buf.as_mut_ptr(), buf.len());
        CStr::from_ptr(buf.as_ptr()).to_string_lossy().into_owned()
    }
}

/// Turns a negative FFmpeg return code into an error.
pub fn chk(code: i32, what: &str) -> anyhow::Result<i32> {
    if code < 0 {
        anyhow::bail!("{what}: {} ({code})", err_text(code));
    }
    Ok(code)
}

pub const fn mktag(a: u8, b: u8, c: u8, d: u8) -> u32 {
    (a as u32) | ((b as u32) << 8) | ((c as u32) << 16) | ((d as u32) << 24)
}
